{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/app-main.json
    The main column of AppShell: the heading, the metric tiles, and the chart panel (beside the activity panel when `activity` is given).
    Props (p): id, title, metrics, chart, activity, cols, density. *}
{var $v_id = ($p['id'] ?? null)}
{var $v_title = ($p['title'] ?? null)}
{var $v_metrics = ($p['metrics'] ?? null)}
{var $v_chart = ($p['chart'] ?? null)}
{var $v_activity = ($p['activity'] ?? null)}
{var $v_cols = ($p['cols'] ?? '1-2')}
{var $v_density = ($p['density'] ?? 'default')}
{capture $c_8}
  {capture $c_1}
    {=ui_text($v_title)}
  {/capture}
  {=ui_include('ui/title/title.latte', ['p' => ['As' => ui_i(2), 'Size' => '2xl', 'Weight' => 'bold', 'Attrs' => ui_attrs(['id', ui_tpl('{0}-title', [$v_id])])], 'children' => $c_1])|noescape}
  {capture $c_3}
    {foreach ui_l($v_metrics) as $v_m}
      {capture $c_2}
        {=ui_include('blocks/stat-tile.latte', ['p' => ['label' => ui_get($v_m, ['label']), 'value' => ui_get($v_m, ['value']), 'icon' => ui_get($v_m, ['icon']), 'hint' => ui_get($v_m, ['hint'])]])|noescape}
      {/capture}
      {=ui_include('ui/box/box.latte', ['p' => ['Attrs' => ui_attrs(['data-testid', 'item'])], 'children' => $c_2])|noescape}
    {/foreach}
  {/capture}
  {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => ui_s($v_cols), 'Class' => 'gap-4', 'Attrs' => ui_attrs(['data-testid', 'items'])], 'children' => $c_3])|noescape}
  {if ui_t($v_activity)}
    {capture $c_6}
      {capture $c_4}
        {=ui_include('blocks/bar-chart.latte', ['p' => ['bars' => ui_get($v_chart, ['series']), 'label' => ui_get($v_chart, ['summary']), 'height' => 144]])|noescape}
      {/capture}
      {=ui_include('blocks/panel.latte', ['p' => ['title' => ui_get($v_chart, ['title']), 'description' => ui_get($v_chart, ['text']), 'id' => ui_tpl('{0}-chart', [$v_id]), 'className' => ui_cnv(['h-full'])], 'children' => $c_4])|noescape}
      {capture $c_5}
        {=ui_include('blocks/timeline.latte', ['p' => ['items' => ui_get($v_activity, ['events'])]])|noescape}
      {/capture}
      {=ui_include('blocks/panel.latte', ['p' => ['title' => ui_get($v_activity, ['title']), 'description' => ui_get($v_activity, ['text']), 'id' => ui_tpl('{0}-feed', [$v_id]), 'className' => ui_cnv(['h-full'])], 'children' => $c_5])|noescape}
    {/capture}
    {=ui_include('ui/grid/grid.latte', ['p' => ['Cols' => '1-2', 'Class' => 'items-stretch gap-4'], 'children' => $c_6])|noescape}
  {else}
    {capture $c_7}
      {=ui_include('blocks/bar-chart.latte', ['p' => ['bars' => ui_get($v_chart, ['series']), 'label' => ui_get($v_chart, ['summary']), 'height' => 144]])|noescape}
    {/capture}
    {=ui_include('blocks/panel.latte', ['p' => ['title' => ui_get($v_chart, ['title']), 'description' => ui_get($v_chart, ['text']), 'id' => ui_tpl('{0}-chart', [$v_id]), 'className' => ui_cnv(['h-full'])], 'children' => $c_7])|noescape}
  {/if}
{/capture}
{=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => ui_s((ui_t(ui_eq($v_density, 'compact')) ? '4' : '6')), 'Align' => 'stretch', 'Class' => 'min-w-0', 'Attrs' => ui_attrs(['data-testid', 'app-main'])], 'children' => $c_8])|noescape}
